    private struct Box { let minX, maxX, minY, maxY: Double }
    private static let boxes: [Box] = polygons.map { p in
        Box(minX: p.map(\.0).min() ?? 0, maxX: p.map(\.0).max() ?? 0, minY: p.map(\.1).min() ?? 0, maxY: p.map(\.1).max() ?? 0)
    }

    static func isLand(lat: Double, lon: Double) -> Bool {
        if lat < -66 { return true }  // 南極
        for (i, p) in polygons.enumerated() {
            let b = boxes[i]
            guard lon >= b.minX, lon <= b.maxX, lat >= b.minY, lat <= b.maxY else { continue }
            if contains(p, x: lon, y: lat) { return true }
        }
        return false
    }

    private static func contains(_ p: [(Double, Double)], x: Double, y: Double) -> Bool {
        var inside = false
        var j = p.count - 1
        for i in 0..<p.count {
            let (xi, yi) = p[i], (xj, yj) = p[j]
            if (yi > y) != (yj > y), x < (xj - xi) * (y - yi) / (yj - yi) + xi { inside.toggle() }
            j = i
        }
        return inside
    }

    /// 陸の点（緯度, 経度）。だいたい同じ面積ごとに 1 点（step 度）
    static func dots(step: Double = 2.6) -> [(lat: Double, lon: Double)] {
        var out: [(Double, Double)] = []
        var lat = -88.0
        while lat <= 86 {
            let lonStep = min(60, step / max(0.05, cos(lat * .pi / 180)))
            var lon = -180.0 + (lat.truncatingRemainder(dividingBy: 2 * step) == 0 ? 0 : lonStep / 2)
            while lon < 180 {
                if isLand(lat: lat, lon: lon) { out.append((lat, lon)) }
                lon += lonStep
            }
            lat += step
        }
        return out
    }

    /// 一度だけ作る
    static let cached: [(lat: Double, lon: Double)] = dots()
}
